<?php
require_once __DIR__ . '/includes/bootstrap.php';
adminRequireLogin();
ensureBlogCategoriesTable();
$tab = ($_GET['tab'] ?? 'posts') === 'categories' ? 'categories' : 'posts';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!adminVerifyPost()) adminRedirect('blog.php?tab=' . $tab, 'Request expired.');
    if (isset($_POST['add'])) adminRedirect('blog.php', addBlogPost($_POST));
    if (isset($_POST['update'])) adminRedirect('blog.php', updateBlogPost((int) ($_POST['post_id'] ?? 0), $_POST));
    if (isset($_POST['delete'])) adminRedirect('blog.php', deleteBlogPost((int) ($_POST['post_id'] ?? 0)) ? 'Post deleted.' : 'Could not delete post.');
    if (isset($_POST['toggle_publish'])) { $id = (int) ($_POST['post_id'] ?? 0); $row = $id ? adminRows('SELECT is_published FROM blog_posts WHERE post_id=' . $id . ' LIMIT 1') : array(); $ok = $row ? runQuery('UPDATE blog_posts SET is_published=? WHERE post_id=?', 'ii', $row[0]['is_published'] ? 0 : 1, $id) : false; adminRedirect('blog.php', $ok ? 'Post visibility updated.' : 'Could not update post status.'); }
    if (isset($_POST['add_category'])) adminRedirect('blog.php?tab=categories', addBlogCategory($_POST));
    if (isset($_POST['update_category'])) adminRedirect('blog.php?tab=categories', updateBlogCategory((int) ($_POST['category_id'] ?? 0), $_POST));
    if (isset($_POST['delete_category'])) adminRedirect('blog.php?tab=categories', deleteBlogCategory((int) ($_POST['category_id'] ?? 0)) ? 'Category deleted.' : 'A category with posts cannot be deleted. Move or delete its posts first.');
    if (isset($_POST['moderate']) && blogInteractionTablesReady()) { $id = (int) ($_POST['comment_id'] ?? 0); $ok = $_POST['moderate'] === 'approve' ? runQuery('UPDATE blog_comments SET is_approved=1 WHERE comment_id=?', 'i', $id) : runQuery('DELETE FROM blog_comments WHERE comment_id=?', 'i', $id); adminRedirect('blog.php', $ok ? 'Comment updated.' : 'Could not update comment.'); }
}
$editing = isset($_GET['edit']) ? getBlogPost((int) $_GET['edit'], false) : null;
$categories = getBlogCategories();
$postsResult = getBlogPosts(false); $posts = $postsResult ? mysqli_fetch_all($postsResult, MYSQLI_ASSOC) : array();
$pending = blogInteractionTablesReady() ? adminRows('SELECT c.comment_id,c.name,c.comment,p.title FROM blog_comments c JOIN blog_posts p ON p.post_id=c.post_id WHERE c.is_approved=0 ORDER BY c.created_at ASC') : array();
$adminTitle = 'Blog'; $adminPage = 'blog'; $adminStyles = array('blog-editor.css'); include __DIR__ . '/includes/header.php';
?>
<div class="admin-menu-tabs admin-blog-tabs" role="tablist" aria-label="Blog workspace"><a href="blog.php"<?php echo $tab === 'posts' ? ' aria-current="page"' : ''; ?>><i class="bi bi-journal-richtext" aria-hidden="true"></i><span>Posts</span><b><?php echo count($posts); ?></b></a><a href="blog.php?tab=categories"<?php echo $tab === 'categories' ? ' aria-current="page"' : ''; ?>><i class="bi bi-bookmarks" aria-hidden="true"></i><span>Categories</span><b><?php echo count($categories); ?></b></a></div>
<?php if ($tab === 'categories') { ?>
<section class="admin-card admin-category-manager admin-blog-category-manager"><div class="admin-toolbar"><div><h2>Blog categories</h2><p class="admin-muted">Organise stories and control which categories appear publicly.</p></div><span class="admin-blog-category-total"><?php echo count($categories); ?> categories</span></div><form method="post" class="admin-form admin-category-form"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><label>Name<input name="name" maxlength="80" required placeholder="Food guides"></label><label>Description<input name="description" maxlength="255" placeholder="Short public description"></label><label class="check"><input type="checkbox" name="is_active" checked> Visible publicly</label><button class="admin-btn" name="add_category"><i class="bi bi-plus-lg"></i>Add category</button></form><div class="admin-blog-category-heading" aria-hidden="true"><span>Category</span><span>Description</span><span>Status</span><span>Actions</span></div><div class="admin-category-table admin-blog-category-list"><?php foreach ($categories as $category) { ?><article><div class="admin-blog-category-name"><strong><?php echo adminEscape($category['name']); ?></strong><span><?php echo (int) $category['post_count']; ?> post<?php echo (int) $category['post_count'] === 1 ? '' : 's'; ?></span></div><p><?php echo adminEscape($category['description'] ?: 'No public description added.'); ?></p><span class="admin-category-badge <?php echo $category['is_active'] ? 'is-active' : 'is-inactive'; ?>"><?php echo $category['is_active'] ? 'Visible' : 'Hidden'; ?></span><div class="admin-blog-category-actions"><details><summary class="admin-icon-button" title="Edit category" aria-label="Edit <?php echo adminEscape($category['name']); ?>"><i class="bi bi-pencil-square"></i></summary><form method="post" class="admin-form admin-inline-editor"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="category_id" value="<?php echo (int) $category['category_id']; ?>"><label>Name<input name="name" maxlength="80" value="<?php echo adminEscape($category['name']); ?>" required></label><label>Description<input name="description" maxlength="255" value="<?php echo adminEscape($category['description']); ?>"></label><label class="check"><input type="checkbox" name="is_active"<?php echo $category['is_active'] ? ' checked' : ''; ?>> Visible publicly</label><button class="admin-btn" name="update_category">Save category</button></form></details><form method="post" class="admin-inline" onsubmit="return confirm('Delete this empty category?')"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="category_id" value="<?php echo (int) $category['category_id']; ?>"><button class="admin-icon-button danger" name="delete_category" title="Delete category" aria-label="Delete <?php echo adminEscape($category['name']); ?>"><i class="bi bi-trash"></i></button></form></div></article><?php } ?><?php if (!$categories) { ?><p class="admin-muted">Create a category before publishing a post.</p><?php } ?></div></section>
<?php } else { ?>
<div class="admin-blog-layout"><section class="admin-card admin-post-editor"><div class="admin-toolbar"><div><h2><?php echo $editing ? 'Edit post' : 'New post'; ?></h2><p class="admin-muted">Create a story with a cover image, category, and publishing controls.</p></div><?php if ($editing) { ?><a class="admin-btn secondary" href="blog.php">Cancel</a><?php } ?></div><form method="post" enctype="multipart/form-data" class="admin-form"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="post_id" value="<?php echo (int) ($editing['post_id'] ?? 0); ?>"><label>Title<input name="title" maxlength="180" value="<?php echo adminEscape($editing['title'] ?? ''); ?>" required></label><label>Excerpt<textarea name="excerpt" rows="3" maxlength="500" required><?php echo adminEscape($editing['excerpt'] ?? ''); ?></textarea><small>Used in article listings and share previews.</small></label><label>Story content<textarea id="blog-content" name="content" required hidden><?php echo adminEscape($editing['content'] ?? ''); ?></textarea><div id="blog-content-editor" class="admin-rich-editor" aria-label="Story content editor"></div><small>Format your story, add links, and upload inline JPG, PNG, or WebP images up to 4 MB.</small></label><label>Category<select name="category" required><?php foreach ($categories as $category) { if (!$category['is_active'] && ($editing['category'] ?? '') !== $category['name']) continue; ?><option value="<?php echo adminEscape($category['name']); ?>"<?php echo ($editing['category'] ?? '') === $category['name'] ? ' selected' : ''; ?>><?php echo adminEscape($category['name']); ?></option><?php } ?></select></label><?php if (!$categories) { ?><p class="admin-notice">Create a category before publishing a post.</p><?php } ?><label>Author<input name="author" maxlength="80" value="<?php echo adminEscape($editing['author'] ?? 'Foodera Team'); ?>" required></label><label>Cover image<input type="file" name="image_file" accept="image/jpeg,image/png,image/webp"<?php echo $editing ? '' : ' required'; ?>><small>JPG, PNG, or WebP up to 4 MB. Used in cards and link previews.</small></label><?php if ($editing) { ?><img class="admin-blog-cover-preview" src="../<?php echo adminEscape($editing['image_path']); ?>" alt="Current cover image"><?php } ?><div class="admin-check-row"><label class="check"><input type="checkbox" name="is_featured" <?php echo !empty($editing['is_featured']) ? 'checked' : ''; ?>> Featured story</label><label class="check"><input type="checkbox" name="is_published" <?php echo !$editing || !empty($editing['is_published']) ? 'checked' : ''; ?>> Publish now</label></div><button class="admin-btn" type="submit" name="<?php echo $editing ? 'update' : 'add'; ?>"<?php echo !$categories ? ' disabled' : ''; ?>><i class="bi bi-send-plus"></i><?php echo $editing ? 'Save changes' : 'Publish post'; ?></button></form></section>
<section class="admin-card"><div class="admin-toolbar"><div><h2>Posts</h2><p class="admin-muted">Edit, publish, preview, or remove stories.</p></div><a href="../blog.php" target="_blank">Public blog <i class="bi bi-box-arrow-up-right"></i></a></div><div class="admin-table-wrap"><table class="admin-table" data-page-size="5"><thead><tr><th>Story</th><th>Category</th><th>Visibility</th><th>Updated</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody><?php foreach ($posts as $post) { ?><tr><td data-label="Story"><div class="admin-post-cell"><img src="../<?php echo adminEscape($post['image_path']); ?>" alt=""><div><strong><?php echo adminEscape($post['title']); ?></strong><small><?php echo adminEscape($post['author']); ?></small></div></div></td><td data-label="Category"><?php echo adminEscape($post['category']); ?></td><td data-label="Visibility"><div class="admin-actions"><span class="admin-badge <?php echo $post['is_published'] ? 'live' : ''; ?>"><?php echo $post['is_published'] ? 'Published' : 'Draft'; ?></span><form method="post" class="admin-inline"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="post_id" value="<?php echo (int) $post['post_id']; ?>"><button class="admin-status-toggle <?php echo $post['is_published'] ? 'is-active' : ''; ?>" type="submit" name="toggle_publish" title="Toggle visibility"><i class="bi <?php echo $post['is_published'] ? 'bi-toggle-on' : 'bi-toggle-off'; ?>"></i></button></form></div></td><td data-label="Updated"><?php echo date('d M Y', strtotime($post['updated_at'])); ?></td><td data-label="Actions"><div class="admin-actions"><a class="admin-icon-button" href="blog.php?edit=<?php echo (int) $post['post_id']; ?>" title="Edit post"><i class="bi bi-pencil-square"></i></a><a class="admin-icon-button" href="../blog.php?post=<?php echo (int) $post['post_id']; ?>" target="_blank" title="View public post"><i class="bi bi-eye"></i></a><form method="post" class="admin-inline" onsubmit="return confirm('Delete this post and its comments?')"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="post_id" value="<?php echo (int) $post['post_id']; ?>"><button class="admin-icon-button danger" name="delete" title="Delete post"><i class="bi bi-trash"></i></button></form></div></td></tr><?php } ?></tbody></table><?php if (!$posts) { ?><p class="admin-muted">No posts yet.</p><?php } ?></div></section></div>
<section class="admin-card"><h2>Comments awaiting approval (<?php echo count($pending); ?>)</h2><?php foreach ($pending as $comment) { ?><article class="admin-comment"><strong><?php echo adminEscape($comment['name']); ?></strong> on <?php echo adminEscape($comment['title']); ?><p><?php echo nl2br(adminEscape($comment['comment'])); ?></p><form method="post" class="admin-actions"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="comment_id" value="<?php echo (int) $comment['comment_id']; ?>"><button class="admin-btn" name="moderate" value="approve">Approve</button><button class="admin-btn danger" name="moderate" value="delete">Delete</button></form></article><?php } ?><?php if (!$pending) { ?><p class="admin-muted">Nothing to review.</p><?php } ?></section>
<?php } ?>
<script src="vendor/quill/quill.js"></script><script src="js/blog-editor.js"></script>
<?php include __DIR__ . '/includes/footer.php'; ?>
